/* ──────────── SECURITY FUNCTIONS ──────────── */
// Security: Sanitize user input
function sanitizeInput(input) {
    const div = document.createElement('div');
    div.textContent = input;
    return div.innerHTML;
}

// Security: Validate user session
function validateUserSession(user) {
    if (!user || typeof user !== 'object') return false;
    if (!user.discordId || !user.username) return false;
    if (!user.token) return false;
    
    // Check if session is too old (30 days)
    if (user.loginTime && Date.now() - user.loginTime > 30 * 24 * 60 * 60 * 1000) {
        return false;
    }
    
    return true;
}

