/* =========================
   CREATE PRODUCT CARD
========================= */
function createProductCard(product) {

    const card = document.createElement("div");

    card.className = "product-card";
    card.dataset.category = product.category;

    if (product.status !== "soon") {
        card.addEventListener("click", () => {
            window.location.href = `product.html?id=${product.id}`;
        });
    }

    let priceHTML = "";

    if (product.oldPrice) {
        priceHTML = `
            <span class="old-price">${product.oldPrice} ر.س</span>
            <span class="new-price">${product.price} ر.س</span>
        `;
    } else if (product.status === "out_of_stock") {
        priceHTML = "نفذت الكمية";
    } else if (product.status === "soon") {
        priceHTML = "قريبًا";
    } else {
        priceHTML = `${product.price} ر.س`;
    }

    card.innerHTML = `
        <div class="product-image-box">
            <img src="${product.image}" alt="${product.title}">
            ${product.oldPrice ? `<span class="discount-badge">خصم</span>` : ""}
            ${product.status === "soon" ? `<span class="soon-badge">قريبًا</span>` : ""}
        </div>

        <h3>${product.title}</h3>

        <p class="price">${priceHTML}</p>

        ${
            product.isSupport
            ?
            `
            <button class="buy-now-btn"
                onclick="event.stopPropagation(); window.open('${product.supportLink}', '_blank')">
                ادعم المتجر
            </button>
            `
            :
            product.status === "available"
            ?
            `
            <button class="add-to-cart"
                data-id="${product.id}"
                data-title="${product.title}"
                data-price="${product.price}"
                data-image="${product.image}">
                إضافة للسلة
            </button>

            <button class="buy-now-btn"
                onclick="event.stopPropagation(); buyNow(${product.id})">
                شراء الآن
            </button>
            `
            :
            `
            <button class="buy-now-btn disabled" disabled>
                شراء الآن
            </button>
            `
        }
    `;

    return card;
}

/* =========================
   PRODUCTS RENDER
========================= */

const productsGrid = document.getElementById("productsGrid");

if (productsGrid) {

    productsGrid.innerHTML = "";

    const urlParams = new URLSearchParams(window.location.search);
    const catParam = urlParams.get("cat");

    let filteredProducts = [...productsData];

    if (catParam) {
        filteredProducts = filteredProducts.filter(p => p.category === catParam);
    }

    // Hide support products from the grid (they have their own section)
    filteredProducts = filteredProducts.filter(p => !p.isSupport);

    filteredProducts.forEach(product => {
        productsGrid.appendChild(createProductCard(product));
    });

    activateAddToCartButtons();
}

/* =========================
   BUY NOW
========================= */

function buyNow(id) {

    const user = JSON.parse(localStorage.getItem("loggedUser") || "null");

    if (!validateUserSession(user)) {
        localStorage.removeItem("loggedUser");
        window.location.href = "account.html";
        return;
    }

    const product = productsData.find(p => p.id === id);

    if (product && product.paypal) {
        // إضافة discordId و plan إلى رابط PayPal كمعاملات
        const paypalUrl = new URL(product.paypal);
        paypalUrl.searchParams.append('discord_id', sanitizeInput(user.discordId));
        paypalUrl.searchParams.append('plan', product.plan || '');
        window.location.href = paypalUrl.toString();
    }
}

/* =========================
   ADD TO CART
========================= */

function activateAddToCartButtons() {

    document.querySelectorAll(".add-to-cart").forEach(button => {

        button.addEventListener("click", e => {

            e.stopPropagation();

            const id = Number(button.dataset.id);

            const title = button.dataset.title;

            const price = Number(button.dataset.price);

            const image = button.dataset.image;

            let cart = JSON.parse(localStorage.getItem("cart") || "[]");

            const existing = cart.find(item => item.id === id);

            if (existing) {
                existing.qty++;
            } else {
                cart.push({
                    id,
                    title,
                    price,
                    image,
                    qty: 1
                });
            }

            localStorage.setItem("cart", JSON.stringify(cart));

            showNiceAlert("تمت إضافة المنتج للسلة");

            updateCartCount();
        });

    });

}

/* =========================
   ALERT
========================= */

function showNiceAlert(text) {

    const alertBox = document.getElementById("niceAlert");

    if (!alertBox) return;

    alertBox.textContent = text;

    alertBox.classList.add("show");

    setTimeout(() => {
        alertBox.classList.remove("show");
    }, 2000);
}

/* =========================
   CART COUNT
========================= */

function updateCartCount() {

    const cart = JSON.parse(localStorage.getItem("cart") || "[]");

    const total = cart.reduce((sum, item) => sum + item.qty, 0);

    const countElement = document.querySelector(".cart-count") || document.getElementById("cartCount");

    if (countElement) {
        countElement.textContent = total;
    }
}

updateCartCount();

/* =========================
   CART ICON
========================= */

const cartIcon = document.querySelector(".cart-icon");

if (cartIcon) {

    cartIcon.addEventListener("click", () => {

        const user = JSON.parse(localStorage.getItem("loggedUser") || "null");

        if (!validateUserSession(user)) {
            localStorage.removeItem("loggedUser");
            window.location.href = "account.html";
            return;
        }

        window.location.href = "checkout.html";
    });

}

/* =========================
   SEARCH
========================= */

const searchIcon = document.querySelector(".search-icon");
const headerEl = document.querySelector("header");
const searchBox = document.querySelector(".search-box");
const searchInput = document.getElementById("searchInput");

function filterProducts(value) {

    if (!productsGrid) return;

    const cards = productsGrid.querySelectorAll(".product-card");

    const keyword = value.trim().toLowerCase();

    cards.forEach(card => {

        const title = card.querySelector("h3").textContent.toLowerCase();

        card.style.display = title.includes(keyword) ? "" : "none";
    });
}

if (searchIcon && headerEl && searchBox && searchInput) {

    searchIcon.addEventListener("click", () => {

        headerEl.classList.toggle("search-open");

        if (headerEl.classList.contains("search-open")) {
            searchInput.focus();
        } else {
            searchInput.value = "";
            filterProducts("");
        }

    });

    document.addEventListener("click", e => {

        if (
            !headerEl.classList.contains("search-open")
        ) return;

        if (
            searchBox.contains(e.target)
            || searchIcon.contains(e.target)
        ) return;

        headerEl.classList.remove("search-open");

        searchInput.value = "";

        filterProducts("");
    });

    searchInput.addEventListener("input", () => {
        filterProducts(searchInput.value);
    });

}

/* =========================
   PROFILE
========================= */

const profileBtn = document.getElementById("profileIcon");
const profileDropdown = document.getElementById("profileDropdown");

if (profileBtn && profileDropdown) {

    profileBtn.addEventListener("click", () => {

        const user = JSON.parse(localStorage.getItem("loggedUser") || "null");

        if (!validateUserSession(user)) {
            localStorage.removeItem("loggedUser");
            window.location.href = "account.html";
            return;
        }

        profileDropdown.classList.toggle("show");
    });

    document.addEventListener("click", e => {

        if (
            !profileBtn.contains(e.target)
            && !profileDropdown.contains(e.target)
        ) {
            profileDropdown.classList.remove("show");
        }

    });

}

/* =========================
   SIDE MENU
========================= */

const sideMenu = document.getElementById("sideMenu");
const sideMenuBtn = document.getElementById("sideMenuBtn");

if (sideMenu && sideMenuBtn) {

    sideMenuBtn.addEventListener("click", () => {

        sideMenu.classList.toggle("open");

        sideMenuBtn.classList.toggle("hidden");
    });

    document.addEventListener("click", e => {

        if (
            !sideMenu.contains(e.target)
            && !sideMenuBtn.contains(e.target)
        ) {
            sideMenu.classList.remove("open");
            sideMenuBtn.classList.remove("hidden");
        }

    });

}

/* =========================
   HEADER SCROLL
========================= */

window.addEventListener("scroll", () => {

    const header = document.querySelector("header");

    if (!header) return;

    if (window.scrollY > 50) {
        header.classList.add("scrolled");
    } else {
        header.classList.remove("scrolled");
    }

});

/* =========================
   FILTERS
========================= */

const filterCategory = document.getElementById("filterCategory");
const filterPrice = document.getElementById("filterPrice");
const filterStatus = document.getElementById("filterStatus");

function applyFilters() {

    if (!productsGrid) return;

    let filtered = [...productsData];

    if (filterCategory && filterCategory.value !== "all") {
        filtered = filtered.filter(p => p.category === filterCategory.value);
    }

    if (filterPrice && filterPrice.value !== "all") {

        if (filterPrice.value === "low") {
            filtered = filtered.filter(p => Number(p.price) < 20);
        }

        if (filterPrice.value === "mid") {
            filtered = filtered.filter(p => Number(p.price) >= 20 && Number(p.price) <= 50);
        }

        if (filterPrice.value === "high") {
            filtered = filtered.filter(p => Number(p.price) > 50);
        }
    }

    if (filterStatus && filterStatus.value !== "all") {
        filtered = filtered.filter(p => p.status === filterStatus.value);
    }

    productsGrid.innerHTML = "";

    filtered.forEach(product => {
        productsGrid.appendChild(createProductCard(product));
    });

    activateAddToCartButtons();
}

if (filterCategory) {
    filterCategory.addEventListener("change", applyFilters);
}

if (filterPrice) {
    filterPrice.addEventListener("change", applyFilters);
}

if (filterStatus) {
    filterStatus.addEventListener("change", applyFilters);
}